type Chapter = 'morning' | 'afternoon' | 'evening';

function getChapter(mission: DailyMission): Chapter {
  if (!mission.time) return 'morning';
  const [hStr] = mission.time.split(':');
  const h = parseInt(hStr, 10);
  if (h < 12) return 'morning';
  if (h < 18) return 'afternoon';
  return 'evening';
}

function freshProgress(): DailyProgress {
  return {
    totalPoints: 0,
    totalMissionsCompleted: 0,
    completedToday: [],
    streakDays: [],
    lastResetDate: todayISO(),
    missions: DEFAULT_MISSIONS,
    history: {},
  };
}

function migrateMission(m: DailyMission): DailyMission {
  const legacy = m as DailyMission & { nameEn?: string; namePt?: string };
  if (m.translationKey || m.name) return m;
  if (legacy.nameEn || legacy.namePt) {
    return { ...m, name: legacy.nameEn ?? legacy.namePt };
  }
  return m;
}

