// ─── Levels ───────────────────────────────────────────────────────────────────

const POINTS_PER_LEVEL = 50;

interface LevelInfo { emoji: string; key: string }
const LEVELS: LevelInfo[] = [
  { emoji: '🌱', key: 'daily.level.recruit'    },
  { emoji: '🧭', key: 'daily.level.explorer'   },
  { emoji: '⚔️', key: 'daily.level.adventurer' },
  { emoji: '🦸', key: 'daily.level.hero'       },
  { emoji: '🏆', key: 'daily.level.champion'   },
  { emoji: '🌟', key: 'daily.level.legend'     },
];

function getLevelIndex(pts: number): number {
  return Math.min(Math.floor(pts / POINTS_PER_LEVEL), LEVELS.length - 1);
}
function getLevelNumber(pts: number): number {
  return Math.floor(pts / POINTS_PER_LEVEL) + 1;
}
function getXpProgress(pts: number): number {
  return ((pts % POINTS_PER_LEVEL) / POINTS_PER_LEVEL) * 100;
}

// ─── Time-of-day ──────────────────────────────────────────────────────────────

function getCurrentChapter(): Chapter {
  const h = new Date().getHours();
  if (h < 12) return 'morning';
  if (h < 18) return 'afternoon';
  return 'evening';
}

function pickFocusMission(missions: DailyMission[], completedToday: string[]): DailyMission | null {
  const undone = missions.filter((m) => !completedToday.includes(m.id));
  if (undone.length === 0) return null;
  const chapter = getCurrentChapter();
  // Try missions in the current chapter first
  const chapterUndone = undone.filter((m) => getChapter(m) === chapter);
  if (chapterUndone.length > 0) return chapterUndone[0];
  // Fallback: next chapter, then any
  const nextChapter: Chapter = chapter === 'morning' ? 'afternoon' : 'evening';
  const next = undone.filter((m) => getChapter(m) === nextChapter);
  if (next.length > 0) return next[0];
  return undone[0];
}

