// ─── Progress ring SVG ────────────────────────────────────────────────────────

interface ProgressRingProps {
  completed: number;
  total: number;
  t: TFunction;
  pulsing: boolean;
}

function ProgressRing({ completed, total, t, pulsing }: ProgressRingProps) {
  const radius = 76;
  const stroke = 14;
  const cx = 90;
  const cy = 90;
  const circumference = 2 * Math.PI * radius;
  const pct = total > 0 ? completed / total : 0;
  const dashOffset = circumference * (1 - pct);

  return (
    <RingWrapper>
      <RingContainer pulsing={pulsing}>
        <svg width={180} height={180} viewBox="0 0 180 180" aria-hidden>
          <circle
            cx={cx} cy={cy} r={radius}
            fill="none"
            stroke={theme.colors.border}
            strokeWidth={stroke}
          />
          <circle
            cx={cx} cy={cy} r={radius}
            fill="none"
            stroke={theme.colors.accent}
            strokeWidth={stroke}
            strokeDasharray={circumference}
            strokeDashoffset={dashOffset}
            strokeLinecap="round"
            transform={`rotate(-90 ${cx} ${cy})`}
            style={{ transition: 'stroke-dashoffset 0.6s cubic-bezier(0.34, 1.56, 0.64, 1)' }}
          />
        </svg>
        <RingInner>
          <RingNumber>{completed}/{total}</RingNumber>
          <RingLabel>{t('daily.progress.today')}</RingLabel>
        </RingInner>
      </RingContainer>
    </RingWrapper>
  );
}

// ─── Sparkline ────────────────────────────────────────────────────────────────

interface SparklineProps {
  history: DayStat[];
  total: number;
  locale: string;
  t: TFunction;
}

function Sparkline({ history, total, locale, t }: SparklineProps) {
  const today = todayISO();
  const dayFmt = new Intl.DateTimeFormat(locale === 'pt' ? 'pt-PT' : 'en-US', { weekday: 'short' });
  const maxCount = Math.max(...history.map((d) => d.count), 1);

  return (
    <SparklineWrapper>
      <SparklineEyebrow>
        <Eyebrow>{t('daily.sparkline.label')}</Eyebrow>
      </SparklineEyebrow>
      <SparklineBars>
        {history.map((d) => {
          const heightPct = d.count / maxCount;
          return (
            <SparklineBar key={d.date} heightPct={heightPct} isToday={d.date === today} />
          );
        })}
      </SparklineBars>
      <SparklineDayLabels>
        {history.map((d) => {
          const label = dayFmt.format(new Date(d.date + 'T00:00:00'));
          return (
            <SparklineDayLabel key={d.date} isToday={d.date === today}>
              {label.slice(0, 3)}
            </SparklineDayLabel>
          );
        })}
      </SparklineDayLabels>
    </SparklineWrapper>
  );
}

// ─── Clock tick ───────────────────────────────────────────────────────────────

function useClockTick(intervalMs: number): Date {
  const [now, setNow] = useState(() => new Date());
  useEffect(() => {
    const id = setInterval(() => setNow(new Date()), intervalMs);
    return () => clearInterval(id);
  }, [intervalMs]);
  return now;
}

