interface AppProps {
  topBarRight?: React.ReactNode;
}

export default function App({ topBarRight }: AppProps) {
  const [locale] = useLocale();
  const t = useMemo(() => createT(locale, APP_KEYS), [locale]);
  const [profile] = useProfile();

  const [loaded, setLoaded] = useState(false);
  const [progress, setProgress] = useState<DailyProgress>(freshProgress);
  const [editMode, setEditMode] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [flashingIds, setFlashingIds] = useState<Set<string>>(new Set());
  const [floatingPoints, setFloatingPoints] = useState<FloatingPoint[]>([]);
  const [levelUpInfo, setLevelUpInfo] = useState<LevelInfo | null>(null);
  const [levelUpExiting, setLevelUpExiting] = useState(false);
  const [confirmReset, setConfirmReset] = useState(false);
  const [dragId, setDragId] = useState<string | null>(null);
  const [overId, setOverId] = useState<string | null>(null);
  const [ringPulsing, setRingPulsing] = useState(false);

  // Skipped focus missions (skip button in focus card)
  const [skippedFocusIds, setSkippedFocusIds] = useState<string[]>([]);

  const floatingIdRef = useRef(0);
  const now = useClockTick(60_000);

  // Load persisted state on mount
  useEffect(() => {
    let cancelled = false;
    loadDailyProgress().then((existing) => {
      if (cancelled) return;
      const today = todayISO();
      if (!existing) {
        setProgress(freshProgress());
      } else {
        const missions = (existing.missions && existing.missions.length > 0 ? existing.missions : DEFAULT_MISSIONS)
          .map((m) => migrateMission(m));
        const history: Record<string, string[]> = { ...(existing.history ?? {}) };
        if (!existing.history && existing.completedToday.length > 0) {
          history[existing.lastResetDate] = [...existing.completedToday];
        }
        if (existing.lastResetDate !== today) {
          if (existing.completedToday.length > 0) {
            history[existing.lastResetDate] = [...existing.completedToday];
          }
          setProgress({
            ...existing,
            completedToday: history[today] ?? [],
            lastResetDate: today,
            missions,
            history,
          });
        } else {
          setProgress({
            ...existing,
            missions,
            history,
            completedToday: history[today] ?? existing.completedToday,
          });
        }
      }
      setLoaded(true);
    });
    return () => { cancelled = true; };
  }, []);

  // Persist on every change (after initial load)
  useEffect(() => {
    if (!loaded) return;
    saveDailyProgress(progress);
  }, [progress, loaded]);

  const toggleMission = useCallback((mission: DailyMission, cardEl: HTMLElement | null) => {
    setProgress((prev) => {
      const alreadyDone = prev.completedToday.includes(mission.id);
      const today = todayISO();

      if (alreadyDone) {
        const newPoints = Math.max(0, prev.totalPoints - mission.points);
        const newCompleted = prev.completedToday.filter((id) => id !== mission.id);
        const newStreakDays = newCompleted.length < 3
          ? prev.streakDays.filter((d) => d !== today)
          : prev.streakDays;
        const newHistory = { ...prev.history, [today]: newCompleted };
        return {
          ...prev,
          totalPoints: newPoints,
          totalMissionsCompleted: Math.max(0, prev.totalMissionsCompleted - 1),
          completedToday: newCompleted,
          streakDays: newStreakDays,
          history: newHistory,
        };
      }

      const newPoints = prev.totalPoints + mission.points;
      const newCompleted = [...prev.completedToday, mission.id];
      const newStreakDays = newCompleted.length >= 3 && !prev.streakDays.includes(today)
        ? [...prev.streakDays, today]
        : prev.streakDays;
      const newHistory = { ...prev.history, [today]: newCompleted };

      setFlashingIds((fids) => new Set(fids).add(mission.id));
      setTimeout(() => {
        setFlashingIds((fids) => {
          const next = new Set(fids);
          next.delete(mission.id);
          return next;
        });
      }, 600);

      setRingPulsing(true);
      setTimeout(() => setRingPulsing(false), 850);
      navigator.vibrate?.(50);

      if (cardEl) {
        const rect = cardEl.getBoundingClientRect();
        const fpId = ++floatingIdRef.current;
        setFloatingPoints((fps) => [...fps, {
          id: fpId,
          value: mission.points,
          x: rect.right - 60,
          y: rect.top + rect.height / 2,
        }]);
        setTimeout(() => {
          setFloatingPoints((fps) => fps.filter((f) => f.id !== fpId));
        }, 1200);
      }

      // Remove from skip list when completed
      setSkippedFocusIds((ids) => ids.filter((id) => id !== mission.id));

      const prevLevel = getLevelIndex(prev.totalPoints);
      const newLevel = getLevelIndex(newPoints);
      if (newLevel > prevLevel) {
        setLevelUpInfo(LEVELS[newLevel]);
        setLevelUpExiting(false);
        setTimeout(() => {
          setLevelUpExiting(true);
          setTimeout(() => setLevelUpInfo(null), 450);
        }, 2000);
      }

      return {
        ...prev,
        totalPoints: newPoints,
        totalMissionsCompleted: prev.totalMissionsCompleted + 1,
        completedToday: newCompleted,
        streakDays: newStreakDays,
        history: newHistory,
      };
    });
  }, []);

  const resetDay = useCallback(() => {
    setProgress((prev) => {
      const today = todayISO();
      const newHistory = { ...prev.history };
      delete newHistory[today];
      return { ...prev, completedToday: [], lastResetDate: today, history: newHistory };
    });
    setSkippedFocusIds([]);
    setConfirmReset(false);
  }, []);

  const deleteMission = useCallback((id: string) => {
    setProgress((prev) => ({
      ...prev,
      missions: prev.missions.filter((m) => m.id !== id),
      completedToday: prev.completedToday.filter((cid) => cid !== id),
    }));
  }, []);

  const addMission = useCallback((mission: DailyMission) => {
    setProgress((prev) => ({ ...prev, missions: [...prev.missions, mission] }));
  }, []);

  const reorderMissions = useCallback((fromId: string, toId: string) => {
    if (fromId === toId) return;
    setProgress((prev) => {
      const arr = prev.missions;
      const fromIdx = arr.findIndex((m) => m.id === fromId);
      const toIdx = arr.findIndex((m) => m.id === toId);
      if (fromIdx < 0 || toIdx < 0) return prev;
      const next = [...arr];
      const [moved] = next.splice(fromIdx, 1);
      next.splice(toIdx, 0, moved);
      return { ...prev, missions: next };
    });
  }, []);

  // ─── Derived values ──────────────────────────────────────────────────────────

  const levelIdx = getLevelIndex(progress.totalPoints);
  const levelNum = getLevelNumber(progress.totalPoints);
  const streak = computeDailyStreak(progress.streakDays);
  const history = useMemo(() => getDailyHistory(progress, 7), [progress]);
  const completedCount = progress.completedToday.length;
  const totalCount = progress.missions.length;
  const remaining = totalCount - completedCount;

  // Focus mission: exclude already-skipped, cycle through undone
  const focusMission = useMemo(() => {
    const undone = progress.missions.filter(
      (m) => !progress.completedToday.includes(m.id) && !skippedFocusIds.includes(m.id)
    );
    if (undone.length === 0) return null;
    const chapter = getCurrentChapter();
    const chapterUndone = undone.filter((m) => getChapter(m) === chapter);
    if (chapterUndone.length > 0) return chapterUndone[0];
    const nextChapter: Chapter = chapter === 'morning' ? 'afternoon' : 'evening';
    const next = undone.filter((m) => getChapter(m) === nextChapter);
    if (next.length > 0) return next[0];
    return undone[0];
  }, [progress.missions, progress.completedToday, skippedFocusIds]);

  // Chapters
  const chapterMissions = useMemo(() => ({
    morning:   progress.missions.filter((m) => getChapter(m) === 'morning'),
    afternoon: progress.missions.filter((m) => getChapter(m) === 'afternoon'),
    evening:   progress.missions.filter((m) => getChapter(m) === 'evening'),
  }), [progress.missions]);

  // ─── Clock & greeting ────────────────────────────────────────────────────────

  const greetKey = (() => {
    const h = now.getHours();
    if (h < 12) return 'daily.greet.morning';
    if (h < 18) return 'daily.greet.afternoon';
    return 'daily.greet.evening';
  })();

  const userName = profile.interests.length > 0
    ? t('daily.greet.defaultName') // no name field on profile yet — use default
    : t('daily.greet.defaultName');

  const timeStr = now.toLocaleTimeString(locale === 'pt' ? 'pt-PT' : 'en-US', { hour: '2-digit', minute: '2-digit' });
  const dateStr = now.toLocaleDateString(locale === 'pt' ? 'pt-PT' : 'en-US', { weekday: 'long', day: 'numeric', month: 'long' });

  const greetingMeta = remaining === 0
    ? t('daily.greet.allDone')
    : t('daily.greet.remaining', { n: remaining, total: totalCount });

  // ─── Chapter tile renderer ───────────────────────────────────────────────────

  function renderChapter(chapterKey: 'morning' | 'afternoon' | 'evening') {
    const labelKey = `daily.chapter.${chapterKey}` as const;
    const missions = chapterMissions[chapterKey];
    const done = missions.filter((m) => progress.completedToday.includes(m.id)).length;

    return (
      <ChapterBlock key={chapterKey}>
        <ChapterHeader>
          <Eyebrow>{t(labelKey)}</Eyebrow>
          <ChapterCount>{t('daily.chapter.count', { done, total: missions.length })}</ChapterCount>
        </ChapterHeader>
        {missions.length === 0 ? (
          <ChapterEmpty>{t('daily.chapter.empty')}</ChapterEmpty>
        ) : (
          <MissionGrid>
            {missions.map((mission) => {
              const completed = progress.completedToday.includes(mission.id);
              const flashing = flashingIds.has(mission.id);
              const name = mission.translationKey ? t(mission.translationKey) : (mission.name ?? '');
              const mColor = mission.color ?? theme.colors.accent;
              const mFrame = mission.frame ?? 'disc';
              return (
                <MissionTile
                  key={mission.id}
                  completed={completed}
                  flashing={flashing}
                  isOver={false}
                  onClick={(e) => toggleMission(mission, e.currentTarget as HTMLElement)}
                  role="checkbox"
                  aria-checked={completed}
                  tabIndex={0}
                  onKeyDown={(e) => {
                    if (e.key === ' ' || e.key === 'Enter') {
                      e.preventDefault();
                      toggleMission(mission, e.currentTarget as HTMLElement);
                    }
                  }}
                >
                  <MissionFrameEl frame={mFrame} emoji={mission.emoji} color={mColor} size={40} />
                  <TileName completed={completed}>{name}</TileName>
                  <TileBottom>
                    <PointsBadge completed={completed}>+{mission.points}</PointsBadge>
                  </TileBottom>
                  {completed && <CheckBadge>✓</CheckBadge>}
                </MissionTile>
              );
            })}
          </MissionGrid>
        )}
      </ChapterBlock>
    );
  }

  // ─── Edit mode renderer ──────────────────────────────────────────────────────

  function renderEditMode() {
    return (
      <div>
        <SectionRow>
          <SectionTitle>{t('daily.sectionMissions')}</SectionTitle>
          <div style={{ display: 'flex', gap: theme.spacing.xs }}>
            <Button
              variant="accent"
              size="sm"
              icon={<Check size={13} />}
              onClick={() => { setEditMode(false); setShowAddModal(false); }}
            >
              {t('daily.done')}
            </Button>
            <IconButton
              onClick={() => setShowAddModal(true)}
              title={t('daily.addMission')}
              aria-label={t('daily.addMission')}
            >
              <Plus size={13} />
            </IconButton>
          </div>
        </SectionRow>
        <EditMissionGrid>
          {progress.missions.map((mission) => {
            const isDragging = dragId === mission.id;
            const isOver = overId === mission.id && dragId !== mission.id;
            const name = mission.translationKey ? t(mission.translationKey) : (mission.name ?? '');
            const mColor = mission.color ?? theme.colors.accent;
            const mFrame = mission.frame ?? 'disc';
            return (
              <EditMissionTile
                key={mission.id}
                isOver={isOver}
                draggable
                style={{ opacity: isDragging ? 0.3 : 1 }}
                onDragStart={(e) => {
                  setDragId(mission.id);
                  e.dataTransfer.effectAllowed = 'move';
                  e.dataTransfer.setData('text/plain', mission.id);
                }}
                onDragOver={(e) => {
                  e.preventDefault();
                  e.dataTransfer.dropEffect = 'move';
                  if (dragId && dragId !== mission.id) setOverId(mission.id);
                }}
                onDragLeave={(e) => {
                  if (e.currentTarget === e.target) setOverId(null);
                }}
                onDrop={(e) => {
                  e.preventDefault();
                  if (dragId) reorderMissions(dragId, mission.id);
                  setDragId(null);
                  setOverId(null);
                }}
                onDragEnd={() => {
                  setDragId(null);
                  setOverId(null);
                }}
              >
                <DragIndicator aria-hidden>
                  <GripVertical size={14} />
                </DragIndicator>
                <MissionFrameEl frame={mFrame} emoji={mission.emoji} color={mColor} size={52} />
                <TileName completed={false}>{name}</TileName>
                <TileBottom>
                  <PointsBadge completed={false}>+{mission.points} pts</PointsBadge>
                </TileBottom>
                <DeleteBadge
                  onClick={(e) => { e.stopPropagation(); deleteMission(mission.id); }}
                  aria-label={t('daily.delete')}
                  title={t('daily.delete')}
                >
                  ×
                </DeleteBadge>
              </EditMissionTile>
            );
          })}
        </EditMissionGrid>
        <div style={{ marginTop: theme.spacing.sm }}>
          <Button variant="ghost" icon={<Plus size={13} />} onClick={() => setShowAddModal(true)}>
            {t('daily.addMission')}
          </Button>
        </div>
      </div>
    );
  }

  // ─── Render ──────────────────────────────────────────────────────────────────

  return (
    <Layout title={t('daily.title')} sidebar={null} topBarRight={topBarRight}>
      <Wrapper>

        {/* 1. Greeting row */}
        <GreetingRow>
          <GreetingLeft>
            <GreetingText>{t(greetKey, { name: userName })}</GreetingText>
            <GreetingMeta>{dateStr} · {timeStr} · {greetingMeta}</GreetingMeta>
          </GreetingLeft>
          <ChipRow>
            <StatPill>🧭 {t('daily.chip.level', { n: levelNum })}</StatPill>
            <StatPill>⭐ {t('daily.chip.points', { n: progress.totalPoints })}</StatPill>
            <StatPill>🔥 {streak > 1 ? t('daily.chip.streak', { n: streak }) : t('daily.chip.streakSingle', { n: streak })}</StatPill>
            <StatPill>✅ {t('daily.chip.done', { n: completedCount })}</StatPill>
          </ChipRow>
        </GreetingRow>

        {/* 2. Focus card + Progress ring */}
        <FocusRingRow>
          <FocusCard>
            <FocusEyebrow>
              <Eyebrow>{t('daily.focus.nextUp')}</Eyebrow>
            </FocusEyebrow>

            {focusMission ? (
              <>
                <FocusEmoji>
                  <MissionFrameEl
                    frame={focusMission.frame ?? 'disc'}
                    emoji={focusMission.emoji}
                    color={focusMission.color ?? theme.colors.accent}
                    size={72}
                  />
                </FocusEmoji>
                <FocusName>
                  {focusMission.translationKey ? t(focusMission.translationKey) : (focusMission.name ?? '')}
                </FocusName>
                <FocusPoints>+{focusMission.points} pts</FocusPoints>
                {focusMission.time && (
                  <FocusTimeChip>{t('daily.focus.timeChip', { time: focusMission.time })}</FocusTimeChip>
                )}
                <FocusActions>
                  <Button
                    variant="primary"
                    onClick={(e) => {
                      const el = (e.target as HTMLElement).closest('button') as HTMLElement | null;
                      toggleMission(focusMission, el);
                    }}
                  >
                    {t('daily.focus.markDone')}
                  </Button>
                  <Button
                    variant="ghost"
                    onClick={() => setSkippedFocusIds((ids) => [...ids, focusMission.id])}
                  >
                    {t('daily.focus.skip')}
                  </Button>
                </FocusActions>
              </>
            ) : (
              <FocusAllDone>
                <FocusAllDoneEmoji>🌟</FocusAllDoneEmoji>
                <FocusAllDoneText>{t('daily.focus.allDone')}</FocusAllDoneText>
                <FocusAllDoneBody>{t('daily.focus.allDoneBody')}</FocusAllDoneBody>
              </FocusAllDone>
            )}
          </FocusCard>

          <ProgressRing
            completed={completedCount}
            total={totalCount}
            t={t}
            pulsing={ringPulsing}
          />
        </FocusRingRow>

        {/* 3+4. Day chapters OR edit mode */}
        {editMode ? renderEditMode() : (
          <ChaptersSection>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
              <Eyebrow>{t('daily.sectionMissions')}</Eyebrow>
              <div style={{ display: 'flex', gap: theme.spacing.xs }}>
                <Button
                  variant="ghost"
                  size="sm"
                  icon={<Pencil size={13} />}
                  onClick={() => setEditMode(true)}
                >
                  {t('daily.edit')}
                </Button>
                <IconButton
                  onClick={() => setShowAddModal(true)}
                  title={t('daily.addMission')}
                  aria-label={t('daily.addMission')}
                >
                  <Plus size={13} />
                </IconButton>
              </div>
            </div>
            {renderChapter('morning')}
            {renderChapter('afternoon')}
            {renderChapter('evening')}
          </ChaptersSection>
        )}

        {/* 5. Sparkline */}
        <Sparkline history={history} total={totalCount} locale={locale} t={t} />

        {/* 6. Footer reset */}
        <FooterRow>
          {confirmReset ? (
            <ConfirmRow>
              <ConfirmText>{t('daily.resetConfirm')}</ConfirmText>
              <ConfirmButtons>
                <Button variant="danger" onClick={resetDay} style={{ flex: 1 }}>
                  {t('daily.confirm')}
                </Button>
                <Button variant="ghost" onClick={() => setConfirmReset(false)} style={{ flex: 1 }}>
                  {t('daily.cancel')}
                </Button>
              </ConfirmButtons>
            </ConfirmRow>
          ) : (
            <Button variant="ghost" onClick={() => setConfirmReset(true)}>
              {t('daily.resetDay')}
            </Button>
          )}
        </FooterRow>

      </Wrapper>

      {/* Floating points */}
      {floatingPoints.map((fp) => (
        <FloatingPointEl key={fp.id} style={{ left: fp.x, top: fp.y }}>
          +{fp.value}
        </FloatingPointEl>
      ))}

      {/* Level-up overlay */}
      {levelUpInfo && (
        <LevelUpOverlay exiting={levelUpExiting}>
          <LevelUpCard>
            <LevelUpEmoji>{levelUpInfo.emoji}</LevelUpEmoji>
            <LevelUpTitle>{t('daily.levelUp')}</LevelUpTitle>
            <LevelUpName>{t(levelUpInfo.key)}</LevelUpName>
          </LevelUpCard>
        </LevelUpOverlay>
      )}

      {showAddModal && (
        <NewMissionModal
          t={t}
          onAdd={(m) => { addMission(m); setShowAddModal(false); }}
          onClose={() => setShowAddModal(false)}
        />
      )}
    </Layout>
  );
}
